const command = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("render"), reportId: z.number().int() }),
  z.object({ kind: z.literal("flush") }),
]);

export async function invoke(raw: unknown) {
  const cmd = command.parse(raw);          // untrusted -> validated
  switch (cmd.kind) {
    case "render": return renderer.render(cmd.reportId);
    case "flush":  return flush();
  }
}
